// Switch clásico en C#
switch (gameState)
{
    case "Menu":
        ShowMenu();
        break;
    case "Playing":
        UpdateGame();
        break;
    case "GameOver":
        ShowGameOver();
        break;
    default:
        Debug.LogError("Estado desconocido");
        break;
}

// Switch expression (C# 8+) - más compacto
string message = gameState switch
{
    "Menu"     => "Estás en el menú",
    "Playing"  => "¡Juego en curso!",
    "GameOver" => "Fin del juego",
    _          => "Estado desconocido"
};

// Patrón común en Unity: switch para estados de enemigo
public enum EnemyState { Idle, Patrol, Chase, Attack, Dead }

void Update()
{
    switch (currentState)
    {
        case EnemyState.Idle:
            IdleBehavior();
            break;
        case EnemyState.Patrol:
            PatrolBehavior();
            break;
        case EnemyState.Chase:
            ChaseBehavior();
            break;
        case EnemyState.Attack:
            AttackBehavior();
            break;
        case EnemyState.Dead:
            // No hacer nada
            break;
    }
}

